package com.trident.job;
import com.trident.user.AppUser;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="jobs")
public class Job {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false) private String title;@Column(nullable=false,length=4000) private String description;private String companyName;private String location;private String type;private String workMode;private String salary;private String skills;private boolean active=true;private LocalDateTime createdAt=LocalDateTime.now();@ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="recruiter_id",nullable=false) private AppUser recruiter;
 public Long getId(){return id;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getCompanyName(){return companyName;}public void setCompanyName(String v){companyName=v;}public String getLocation(){return location;}public void setLocation(String v){location=v;}public String getType(){return type;}public void setType(String v){type=v;}public String getWorkMode(){return workMode;}public void setWorkMode(String v){workMode=v;}public String getSalary(){return salary;}public void setSalary(String v){salary=v;}public String getSkills(){return skills;}public void setSkills(String v){skills=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}public LocalDateTime getCreatedAt(){return createdAt;}public AppUser getRecruiter(){return recruiter;}public void setRecruiter(AppUser v){recruiter=v;}
}